        Editor(Activity a,Wallpapers.Config initial,String grant){super(a);activity=a;unusedGrant=grant;skin=CarUi.skin(a);draft=initial.copy();requestWindowFeature(Window.FEATURE_NO_TITLE);
            LinearLayout panel=col();panel.setTag(CarUi.OWN);panel.setPadding(d(22),d(18),d(22),d(18));
            LinearLayout heading=row();heading.addView(text("壁纸中心",26,true),new LinearLayout.LayoutParams(0,-2,1));heading.addView(button("关闭",new View.OnClickListener(){@Override public void onClick(View v){dismiss();}}));panel.addView(heading,new LinearLayout.LayoutParams(-1,-2));
            status=text("预览不会改变当前壁纸，点击应用后保存",15,false);status.setTextColor(skin.muted);status.setPadding(0,d(8),0,d(12));panel.addView(status);
            preview=new WallpaperView(a,true);preview.setContentDescription("动态壁纸实时预览");controls=col();controls.setPadding(d(10),0,d(6),0);ScrollView scroll=new ScrollView(a);scroll.setFillViewport(false);scroll.addView(controls,new ScrollView.LayoutParams(-1,-2));
            Work work=new Work(a,preview,scroll);panel.addView(work,new LinearLayout.LayoutParams(-1,0,1));
            LinearLayout footer=row();footer.setPadding(0,d(14),0,0);footer.addView(button("取消",new View.OnClickListener(){@Override public void onClick(View v){dismiss();}}),new LinearLayout.LayoutParams(0,-2,1));TextView apply=button("应用壁纸",new View.OnClickListener(){@Override public void onClick(View v){if(draft.mode.equals("video")&&draft.uri.isEmpty()){CarUi.message(activity,"请先选择一个本地视频");return;}if(draft.mode.equals("static")&&draft.staticImage>=2&&!preview.staticAvailable()){CarUi.message(activity,"图片不可读取，请重新选择静态壁纸");return;}if(!unusedGrant.equals(draft.uri))Wallpapers.releaseGrant(activity,unusedGrant);Wallpapers.save(activity,draft);applied=true;dismiss();}});apply.setTextColor(skin.onAccent);apply.setBackground(CarUi.buttonBackground(a,skin.accent,skin.pressedAccent,skin.onAccent,22));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.leftMargin=d(12);footer.addView(apply,p);panel.addView(footer);setContentView(panel);populate();
        }
